#include "training.h"
#include "hospital.h"
#include "fishing.h"
#include "legacy_game_v16.h"
#include <assert.h>
#include <stddef.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
static void init(pp_game *g,unsigned level){pp_init(g,123);assert(pp_choose_starter(g,1)==PP_OK);g->count=3;for(unsigned i=0;i<3;i++){g->pets[i]=(pp_pet){.species=i+1,.food=90,.clean=90,.health=100,.mood=90,.energy=100};g->growth[i]=(pp_growth){.level=level};for(unsigned j=0;j<6;j++)g->identity[i].iv[j]=15;}pp_tick(g,0,0);assert(pp_valid(g));}
static void roundtrip(pp_game *g){unsigned n=pp_save_size(g);void *p=malloc(n);assert(pp_valid(g));assert(pp_save_write(g,p,n,123));pp_game other={0};assert(pp_save_read(&other,p,n,NULL));assert(pp_checksum(g)==pp_checksum(&other));free(p);pp_dispose(g);*g=other;}
static void scenes(void){pp_game g={0};init(&g,1);unsigned coins=g.coins;assert(pp_prosperity(&g)==3);assert(pp_scene(&g,1)==PP_OK&&g.coins==coins);assert(pp_scene(&g,2)==PP_NOT_READY&&g.coins==coins);for(unsigned d=0;d<125;d++)g.dex_history[d/8]|=1u<<(d%8);pp_tick(&g,0,0);assert(pp_scene(&g,12)==PP_OK&&g.coins==coins);roundtrip(&g);assert(g.scenes==8191);pp_dispose(&g);}
static void care(void){pp_game g={0};init(&g,20);g.pets[0]=(pp_pet){.species=1,.food=11,.clean=12,.health=13,.mood=14,.energy=15,.sleeping=1};pp_hospital h;pp_hospital_init(&h,123);h.phase=PP_HOSPITAL_WON;assert(pp_hospital_claim(&h,&g)==PP_OK);assert(g.pets[0].health==60&&g.pets[0].food==11&&g.pets[0].clean==12&&g.pets[0].mood==14&&g.pets[0].energy==15&&g.pets[0].sleeping);unsigned hp=pp_care_hp(&g,0);assert(pp_hospital_treat(&g,0)==PP_OK&&g.pets[0].health==100&&pp_care_hp(&g,0)>hp);g.pets[0].energy=20;g.pets[0].sleeping=0;pp_tick(&g,3600,0);assert(g.pets[0].energy==30);g.pets[0].energy=10;g.pets[0].sleeping=1;pp_tick(&g,7200,0);assert(g.pets[0].energy==60&&!g.pets[0].sleeping);roundtrip(&g);pp_dispose(&g);}
static void individual(void){pp_game g={0};init(&g,20);unsigned n=pp_award_battle_xp(&g,0,20,20,1,1,true,1);assert(n==7&&g.pet_balance[0].xp_fraction==700000);for(unsigned i=0;i<9;i++)pp_training_cost(&g,0,false);assert(g.pet_balance[0].battles==9);assert(pp_reserve_pet(&g,0)==PP_OK);pp_stored_pet p;assert(pp_warehouse_get(&g,0,&p)&&p.balance.xp_fraction==700000&&p.balance.battles==9);assert(pp_replace_pet(&g,0,0)==PP_OK);assert(g.pet_balance[0].battles==9);pp_training_cost(&g,0,false);assert(g.pet_balance[0].battles==10&&g.pets[0].food==89);roundtrip(&g);assert(pp_award_battle_xp(&g,0,20,60,0,3,false,1)==0);pp_dispose(&g);}
static void walking(void){pp_game g={0};init(&g,20);unsigned coins=g.coins;pp_record_steps(&g,5000);assert(g.coins==coins+150&&g.wild_queue==3);pp_record_steps(&g,10000);assert(g.coins==coins+200&&g.total_steps==15000);unsigned xp=g.growth[0].xp;pp_record_steps(&g,1000);assert(g.growth[0].xp==xp);roundtrip(&g);pp_wild_scene(&g,true);assert(g.wild.phase==PP_WILD_PENDING);assert(pp_wild_alert_remaining(&g)==180);for(unsigned i=0;i<179;i++){pp_tick(&g,1,0);pp_wild_scene(&g,true);}assert(pp_wild_alert_remaining(&g)==1);pp_tick(&g,1000,0);pp_wild_scene(&g,false);assert(pp_wild_alert_remaining(&g)==1);pp_tick(&g,1,0);pp_wild_scene(&g,true);assert(g.wild.phase==PP_WILD_NONE&&g.wild_queue==2);for(unsigned i=0;i<61;i++){pp_tick(&g,1,0);pp_wild_scene(&g,true);}assert(g.wild.phase==PP_WILD_PENDING);roundtrip(&g);pp_dispose(&g);}
static void jobs(void){for(unsigned level=1;level<=41;level+=20)for(unsigned count=1;count<=3;count++){pp_game g={0};init(&g,level);pp_training t;pp_training_init(&t,123);unsigned picks[]={0,1,2};assert(pp_training_job_start(&t,&g,(level-1)/10,picks,count)==PP_OK);while(g.training.status==1)pp_training_job_advance(&t,&g,10000);assert(g.training.status==2&&g.training.rounds>0);assert(g.growth[0].level<=level+4);assert(g.training.coins<100);for(unsigned i=5;i<PP_SHOP_ITEMS;i++)assert(!g.training.items[i]);roundtrip(&g);assert(pp_training_restore(&t,&g));pp_training_close(&t);pp_dispose(&g);}pp_game g={0};init(&g,20);assert(pp_reserve_pet(&g,2)==PP_OK);unsigned pick=PP_PETS;pp_training t;pp_training_init(&t,1);uint32_t checksum=pp_checksum(&g);assert(pp_training_job_start(&t,&g,0,&pick,1)==PP_INVALID&&pp_checksum(&g)==checksum);pp_dispose(&g);}
static void legacy(void){pp_game g={0};init(&g,20);g.coins=9123;pp_game_v16 old={0};memcpy(&old,&g,offsetof(pp_game,training));old.version=16;unsigned fixed=offsetof(pp_game_v16,overflow),bytes=16+fixed;unsigned char *blob=calloc(1,bytes);memcpy(blob+4,&bytes,4);memcpy(blob+16,&old,fixed);unsigned hash=2166136261u;for(unsigned i=4;i<bytes;i++)hash=(hash^blob[i])*16777619u;memcpy(blob,&hash,4);pp_game copy={0};assert(pp_save_read(&copy,blob,bytes,NULL));assert(copy.version==17&&copy.coins==9123&&copy.count==3&&!copy.pet_balance[0].xp_fraction);roundtrip(&copy);free(blob);pp_dispose(&copy);pp_dispose(&g);}
static void cap(void){pp_game g={0};init(&g,59);g.growth[0].xp=1179;assert(pp_award_battle_xp(&g,0,59,60,1,1,true,1)==1);assert(g.growth[0].level==60&&!g.growth[0].xp&&!g.pet_balance[0].xp_fraction);assert(!pp_award_battle_xp(&g,0,60,60,1,1,true,1));pp_dispose(&g);}
int main(void){cap();scenes();care();individual();walking();jobs();legacy();puts("PASS: balance, prosperity, individual costs, hospital, step caps, visible encounter queue, courtyard-only training and v16 migration");}
